// ---------------------------------------------------------------------------
// Client-side search. Fetches /search.json once (generated by Jekyll at
// build time) and filters it in the browser as the user types.
// ---------------------------------------------------------------------------
document.addEventListener("DOMContentLoaded", () => {
  const toggle = document.getElementById("search-toggle");
  const overlay = document.getElementById("search-overlay");
  const input = document.getElementById("search-input");
  const resultsEl = document.getElementById("search-results");

  if (!toggle || !overlay || !input || !resultsEl) return;

  let data = null;

  function openSearch() {
    overlay.hidden = false;
    input.value = "";
    resultsEl.innerHTML = "";
    input.focus();
    if (!data) {
      fetch("/search.json")
        .then((r) => r.json())
        .then((json) => { data = json; })
        .catch(() => { resultsEl.innerHTML = '<p class="search-empty">Search index failed to load.</p>'; });
    }
  }

  function closeSearch() {
    overlay.hidden = true;
  }

  function escapeHtml(str) {
    const div = document.createElement("div");
    div.textContent = str;
    return div.innerHTML;
  }

  function render(matches) {
    if (matches.length === 0) {
      resultsEl.innerHTML = '<p class="search-empty">No results.</p>';
      return;
    }
    resultsEl.innerHTML = matches
      .map((m) => {
        const label = m.type === "chapter" ? m.series_title : "note";
        return `
          <a class="search-result" href="${m.url}">
            <span class="search-result-type">${escapeHtml(label)}</span>
            <span class="search-result-title">${escapeHtml(m.title)}</span>
            <span class="search-result-desc">${escapeHtml(m.description)}</span>
          </a>
        `;
      })
      .join("");
  }

  toggle.addEventListener("click", openSearch);

  overlay.addEventListener("click", (e) => {
    if (e.target === overlay) closeSearch();
  });

  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && !overlay.hidden) closeSearch();
    if ((e.metaKey || e.ctrlKey) && e.key === "/") {
      e.preventDefault();
      openSearch();
    }
  });

  input.addEventListener("input", () => {
    const q = input.value.trim().toLowerCase();
    if (!data || q.length < 1) {
      resultsEl.innerHTML = "";
      return;
    }
    const matches = data
      .filter((item) => {
        const haystack = (
          item.title + " " + item.description + " " + (item.tags || []).join(" ")
        ).toLowerCase();
        return haystack.includes(q);
      })
      .slice(0, 8);
    render(matches);
  });
});
